{
  "items": [
    {
      "name": "Polynomial.sum",
      "module_name": "Mathlib.Algebra.Polynomial.Basic",
      "kind": "definition",
      "type": "{R : Type u} → [inst : Semiring R] → {S : Type u_1} → [AddCommMonoid S] → Polynomial R → (ℕ → R → S) → S"
    },
    {
      "name": "Polynomial.as_sum_support_C_mul_X_pow",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Support",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] (p : Polynomial R), p = ∑ i ∈ p.support, Polynomial.C (p.coeff i) * Polynomial.X ^ i"
    },
    {
      "name": "Polynomial.sum_over_range",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Support",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S : Type v} [inst : Semiring R] [inst_1 : AddCommMonoid S] (p : Polynomial R) {f : ℕ → R → S},\n  (∀ (n : ℕ), f n 0 = 0) → p.sum f = ∑ a ∈ Finset.range (p.natDegree + 1), f a (p.coeff a)"
    },
    {
      "name": "Polynomial.sum_fin",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Support",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S : Type v} [inst : Semiring R] [inst_1 : AddCommMonoid S] (f : ℕ → R → S),\n  (∀ (i : ℕ), f i 0 = 0) → ∀ {n : ℕ} {p : Polynomial R}, p.degree < ↑n → ∑ i, f (↑i) (p.coeff ↑i) = p.sum f"
    },
    {
      "name": "Polynomial.natDegree_sum_le_of_forall_le",
      "module_name": "Mathlib.Algebra.Polynomial.BigOperators",
      "kind": "theorem",
      "type": "∀ {ι : Type w} (s : Finset ι) {S : Type u_1} [inst : Semiring S] {n : ℕ} (f : ι → Polynomial S),\n  (∀ i ∈ s, (f i).natDegree ≤ n) → (∑ i ∈ s, f i).natDegree ≤ n"
    },
    {
      "name": "Polynomial.ofFinsupp_sum",
      "module_name": "Mathlib.Algebra.Polynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] {ι : Type u_1} (s : Finset ι) (f : ι → AddMonoidAlgebra R ℕ),\n  { toFinsupp := ∑ i ∈ s, f i } = ∑ i ∈ s, { toFinsupp := f i }"
    },
    {
      "name": "Polynomial.degree_sum_fin_lt",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Operations",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] {n : ℕ} (f : Fin n → R), (∑ i, Polynomial.C (f i) * Polynomial.X ^ ↑i).degree < ↑n"
    },
    {
      "name": "MvPolynomial.vars_sum_subset",
      "module_name": "Mathlib.Algebra.MvPolynomial.Variables",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] {ι : Type u_3} (t : Finset ι) (φ : ι → MvPolynomial σ R)\n  [inst_1 : DecidableEq σ], (∑ i ∈ t, φ i).vars ⊆ t.biUnion fun i => (φ i).vars"
    }
  ]
}

