      "kind": "theorem",
      "type": "∀ {M : Type u_1} [inst : CompleteLattice M] [inst_1 : AddGroup M] [AddLeftMono M] [AddRightMono M] (s t : Set M),\n  sSup (s + t) = sSup s + sSup t"
